update public.cms_pages set draft_content=jsonb_set(draft_content,'{description}',to_jsonb('از انتخاب روش همراهی تا آماده‌سازی مدارک؛ مسیرت را با چند قدم کوتاه شروع کن. قیمت را قبل از تصمیم می‌بینی.'::text)) where slug='home' and draft_content->>'description'='برای یک فرصت تازه، لازم نیست مسیر را تنها بروید. از شناخت لاتاری تا آماده‌سازی و بررسی درخواست، قدم‌به‌قدم همراه شما هستیم.';
update public.cms_pages set published_content=jsonb_set(published_content,'{description}',to_jsonb('از انتخاب روش همراهی تا آماده‌سازی مدارک؛ مسیرت را با چند قدم کوتاه شروع کن. قیمت را قبل از تصمیم می‌بینی.'::text)) where slug='home' and published_content->>'description'='برای یک فرصت تازه، لازم نیست مسیر را تنها بروید. از شناخت لاتاری تا آماده‌سازی و بررسی درخواست، قدم‌به‌قدم همراه شما هستیم.';
