update public.cms_pages set draft_content=jsonb_set(draft_content,'{text2}',to_jsonb('این صفحه روش کار مسیر تعاملی، گفت‌وگو و پرونده مشتری را توضیح می‌دهد. در حالت آزمایشی، وجه یا پرونده خدماتی واقعی ایجاد نمی‌شود؛ از اطلاعات ساختگی استفاده کنید.'::text)) where slug='privacy' and draft_content->>'text2'='این صفحه، پیش‌نویس سیاست حریم خصوصی نسخه اولیه است. دریافت درخواست، پرداخت و مدارک واقعی در این نسخه فعال نیست.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text2}',to_jsonb('این صفحه روش کار مسیر تعاملی، گفت‌وگو و پرونده مشتری را توضیح می‌دهد. در حالت آزمایشی، وجه یا پرونده خدماتی واقعی ایجاد نمی‌شود؛ از اطلاعات ساختگی استفاده کنید.'::text)) where slug='privacy' and published_content->>'text2'='این صفحه، پیش‌نویس سیاست حریم خصوصی نسخه اولیه است. دریافت درخواست، پرداخت و مدارک واقعی در این نسخه فعال نیست.';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text3}',to_jsonb('فرم و سفارش'::text)) where slug='privacy' and draft_content->>'text3'='فرم فعلی چه می‌کند؟';
update public.cms_pages set published_content=jsonb_set(published_content,'{text3}',to_jsonb('فرم و سفارش'::text)) where slug='privacy' and published_content->>'text3'='فرم فعلی چه می‌کند؟';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text4}',to_jsonb('پیش از تأیید نهایی، نام، نام خانوادگی، ایمیل و شماره تماس فقط در حافظه صفحه هستند. هنگام تأیید سفارش در سرویس فعال، این اطلاعات همراه با خدمت، قیمت و نتیجه سفارش در Supabase ذخیره می‌شوند و تیم مجاز به آن‌ها دسترسی دارد. در حالت پیش‌نمایش غیرفعال، فرم اطلاعات را ارسال نمی‌کند.'::text)) where slug='privacy' and draft_content->>'text4'='اطلاعات واردشده فقط در حافظه همین صفحه برای بررسی ساختار فرم استفاده می‌شود. در حالت پیش‌نمایش به سرور ارسال و در مرورگر ذخیره دائمی نمی‌شود. با بستن یا تازه‌کردن صفحه از دست می‌رود.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text4}',to_jsonb('پیش از تأیید نهایی، نام، نام خانوادگی، ایمیل و شماره تماس فقط در حافظه صفحه هستند. هنگام تأیید سفارش در سرویس فعال، این اطلاعات همراه با خدمت، قیمت و نتیجه سفارش در Supabase ذخیره می‌شوند و تیم مجاز به آن‌ها دسترسی دارد. در حالت پیش‌نمایش غیرفعال، فرم اطلاعات را ارسال نمی‌کند.'::text)) where slug='privacy' and published_content->>'text4'='اطلاعات واردشده فقط در حافظه همین صفحه برای بررسی ساختار فرم استفاده می‌شود. در حالت پیش‌نمایش به سرور ارسال و در مرورگر ذخیره دائمی نمی‌شود. با بستن یا تازه‌کردن صفحه از دست می‌رود.';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text5}',to_jsonb('گفت‌وگو و دسترسی این مرورگر'::text)) where slug='privacy' and draft_content->>'text5'='پیش از فعال شدن خدمات';
update public.cms_pages set published_content=jsonb_set(published_content,'{text5}',to_jsonb('گفت‌وگو و دسترسی این مرورگر'::text)) where slug='privacy' and published_content->>'text5'='پیش از فعال شدن خدمات';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text6}',to_jsonb('پاسخ‌های راهنمای خودکار از متن‌های از پیش تعیین‌شده هستند. پیام ارسالی به کارشناس در Supabase ذخیره می‌شود و تیم به آن دسترسی دارد. یک کوکی خصوصی ۳۰روزه برای مشاهده سفارش و گفت‌وگو در همین مرورگر استفاده می‌شود؛ پاک‌کردن کوکی یا تغییر مرورگر این دسترسی را از بین می‌برد. هیچ مدرک هویتی یا اطلاعات کارت را در چت نفرستید. برای اصلاح یا درخواست حذف اطلاعات از گفت‌وگو با کارشناس استفاده کنید. سیاست نهایی نگهداری سفارش‌ها و پیام‌ها پیش از استفاده عملیاتی باید اعلام شود.'::text)) where slug='privacy' and draft_content->>'text6'='روش دریافت و نگهداری اطلاعات، ارائه‌دهندگان زیرساخت، افراد دارای دسترسی، مدت نگهداری، شرایط حذف و راه ارتباط برای درخواست اصلاح یا حذف باید تکمیل و اعلام شوند.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text6}',to_jsonb('پاسخ‌های راهنمای خودکار از متن‌های از پیش تعیین‌شده هستند. پیام ارسالی به کارشناس در Supabase ذخیره می‌شود و تیم به آن دسترسی دارد. یک کوکی خصوصی ۳۰روزه برای مشاهده سفارش و گفت‌وگو در همین مرورگر استفاده می‌شود؛ پاک‌کردن کوکی یا تغییر مرورگر این دسترسی را از بین می‌برد. هیچ مدرک هویتی یا اطلاعات کارت را در چت نفرستید. برای اصلاح یا درخواست حذف اطلاعات از گفت‌وگو با کارشناس استفاده کنید. سیاست نهایی نگهداری سفارش‌ها و پیام‌ها پیش از استفاده عملیاتی باید اعلام شود.'::text)) where slug='privacy' and published_content->>'text6'='روش دریافت و نگهداری اطلاعات، ارائه‌دهندگان زیرساخت، افراد دارای دسترسی، مدت نگهداری، شرایط حذف و راه ارتباط برای درخواست اصلاح یا حذف باید تکمیل و اعلام شوند.';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text8}',to_jsonb('ارسال مدارک فقط از بخش خصوصی پرتال، با حساب و ایمیل تأییدشده و پس از فعال‌سازی دریافت توسط کارشناس انجام می‌شود. مدارک تا پایان یا لغو پرونده و ۹۰ روز پس از آن نگهداری می‌شوند؛ پس از مهلت، دسترسی قطع و پاک‌سازی با اقدام تیم انجام می‌شود. اصل و نسخه بازیابی رمزگذاری‌شده در همان پروژه Supabase هستند.'::text)) where slug='privacy' and draft_content->>'text8'='در این نسخه هیچ مدرکی دریافت نمی‌شود. پیش از فعال شدن مرحله مدارک، شیوه ارسال خصوصی و شرایط نگهداری آن‌ها مشخص خواهد شد. مدرک واقعی را در فرم تماس یا نشانی عمومی ارسال نکنید.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text8}',to_jsonb('ارسال مدارک فقط از بخش خصوصی پرتال، با حساب و ایمیل تأییدشده و پس از فعال‌سازی دریافت توسط کارشناس انجام می‌شود. مدارک تا پایان یا لغو پرونده و ۹۰ روز پس از آن نگهداری می‌شوند؛ پس از مهلت، دسترسی قطع و پاک‌سازی با اقدام تیم انجام می‌شود. اصل و نسخه بازیابی رمزگذاری‌شده در همان پروژه Supabase هستند.'::text)) where slug='privacy' and published_content->>'text8'='در این نسخه هیچ مدرکی دریافت نمی‌شود. پیش از فعال شدن مرحله مدارک، شیوه ارسال خصوصی و شرایط نگهداری آن‌ها مشخص خواهد شد. مدرک واقعی را در فرم تماس یا نشانی عمومی ارسال نکنید.';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text12}',to_jsonb('ابزار تحلیل یا تبلیغات خارجی به مسیر اضافه نشده است. رویداد محلی پیشرفت فقط نام مرحله را دارد؛ نام، ایمیل، موبایل، متن چت و کد تخفیف در آن قرار نمی‌گیرند. سرویس میزبانی ممکن است لاگ فنی خودش را ایجاد کند.'::text)) where slug='privacy' and draft_content->>'text12'='در کد این نسخه، ابزار تبلیغاتی یا تحلیل رفتار کاربر اضافه نشده است. سرویس میزبانی ممکن است طبق سیاست خودش لاگ فنی ایجاد کند؛ جزئیات پس از انتخاب میزبان نهایی اعلام می‌شود.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text12}',to_jsonb('ابزار تحلیل یا تبلیغات خارجی به مسیر اضافه نشده است. رویداد محلی پیشرفت فقط نام مرحله را دارد؛ نام، ایمیل، موبایل، متن چت و کد تخفیف در آن قرار نمی‌گیرند. سرویس میزبانی ممکن است لاگ فنی خودش را ایجاد کند.'::text)) where slug='privacy' and published_content->>'text12'='در کد این نسخه، ابزار تبلیغاتی یا تحلیل رفتار کاربر اضافه نشده است. سرویس میزبانی ممکن است طبق سیاست خودش لاگ فنی ایجاد کند؛ جزئیات پس از انتخاب میزبان نهایی اعلام می‌شود.';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text2}',to_jsonb('این شرایط پیش‌نویس است. حالت شبیه‌ساز و درگاه آزمایشی، خدمت واقعی یا پرداخت واقعی ایجاد نمی‌کنند. دریافت وجه واقعی پس از نهایی‌شدن شرایط و فعال‌سازی صریح درگاه ممکن می‌شود.'::text)) where slug='terms' and draft_content->>'text2'='این شرایط، پیش‌نویس نسخه اولیه است. ثبت درخواست و پرداخت هنوز فعال نشده و نسخه نهایی پیش از دریافت وجه اعلام می‌شود.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text2}',to_jsonb('این شرایط پیش‌نویس است. حالت شبیه‌ساز و درگاه آزمایشی، خدمت واقعی یا پرداخت واقعی ایجاد نمی‌کنند. دریافت وجه واقعی پس از نهایی‌شدن شرایط و فعال‌سازی صریح درگاه ممکن می‌شود.'::text)) where slug='terms' and published_content->>'text2'='این شرایط، پیش‌نویس نسخه اولیه است. ثبت درخواست و پرداخت هنوز فعال نشده و نسخه نهایی پیش از دریافت وجه اعلام می‌شود.';
update public.cms_pages set draft_content=jsonb_set(draft_content,'{text6}',to_jsonb('تعرفه‌ها به تومان و برای هر نفر هستند؛ تعرفه عادی برنامه‌ریزی‌شده به معنای سابقه فروش قبلی نیست. کد تخفیف به خدمت، زمان، محیط و ظرفیت کمپین وابسته است و برای هر ایمیل یک بار مصرف می‌شود. نمایش قیمت، ظرفیت را رزرو نمی‌کند؛ تأیید سفارش رزرو را انجام می‌دهد. با تخفیف صددرصد نیازی به پرداخت بانکی نیست. هزینه رسمی احتمالی، عکاسی و خدمات پس از انتخاب، جداگانه توافق می‌شوند.'::text)) where slug='terms' and draft_content->>'text6'='قیمت‌های صفحه، برنامه پیشنهادی تعرفه خدمات به تومان و به‌ازای هر نفر است. تعرفه عادی برنامه‌ریزی‌شده به معنای سابقه فروش قبلی نیست. هزینه رسمی احتمالی، عکاسی و خدمات پس از انتخاب شدن، در صورت نیاز و پس از توافق جداگانه تعیین می‌شوند.';
update public.cms_pages set published_content=jsonb_set(published_content,'{text6}',to_jsonb('تعرفه‌ها به تومان و برای هر نفر هستند؛ تعرفه عادی برنامه‌ریزی‌شده به معنای سابقه فروش قبلی نیست. کد تخفیف به خدمت، زمان، محیط و ظرفیت کمپین وابسته است و برای هر ایمیل یک بار مصرف می‌شود. نمایش قیمت، ظرفیت را رزرو نمی‌کند؛ تأیید سفارش رزرو را انجام می‌دهد. با تخفیف صددرصد نیازی به پرداخت بانکی نیست. هزینه رسمی احتمالی، عکاسی و خدمات پس از انتخاب، جداگانه توافق می‌شوند.'::text)) where slug='terms' and published_content->>'text6'='قیمت‌های صفحه، برنامه پیشنهادی تعرفه خدمات به تومان و به‌ازای هر نفر است. تعرفه عادی برنامه‌ریزی‌شده به معنای سابقه فروش قبلی نیست. هزینه رسمی احتمالی، عکاسی و خدمات پس از انتخاب شدن، در صورت نیاز و پس از توافق جداگانه تعیین می‌شوند.';
